    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A surprise twist: instead of another grand stone wall, we wander the little lanes and workshops of San Blas.",
      "start": "10:30"
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch with proper vegetarian plates, and a long table for four to rest our feet.",
      "start": "12:00"
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "The cathedral stays as the afternoon anchor, but now it feels like a bonus after the quiet morning.",
